class Solution {

    private int cmpRev(String x, String y) {
        x = x.replaceFirst("^0+", "");
        y = y.replaceFirst("^0+", "");
        if (x.length() != y.length()) return x.length() > y.length() ? 1 : -1;
        int c = x.compareTo(y);
        return c > 0 ? 1 : c < 0 ? -1 : 0;
    }

    public int compareReleases(String a, String b) {
        String[] ra = a.split("\\."), rb = b.split("\\.");
        for (int k = 0; k < Math.max(ra.length, rb.length); k++) {
            String x = k < ra.length ? ra[k] : "0", y = k < rb.length ? rb[k] : "0";
            int c = cmpRev(x, y);
            if (c != 0) return c;
        }
        return 0;
    }
}

