class Solution {
    static vector<string> split(const string& s) {
        vector<string> out(1);
        for (char c : s) if (c == '.') out.emplace_back(); else out.back() += c;
        return out;
    }

    static int cmpRev(string x, string y) {
        x.erase(0, min(x.find_first_not_of('0'), x.size()));
        y.erase(0, min(y.find_first_not_of('0'), y.size()));
        if (x.size() != y.size()) return x.size() > y.size() ? 1 : -1;
        return x == y ? 0 : x > y ? 1 : -1;
    }

public:
    int compareReleases(string& a, string& b) {
        vector<string> ra = split(a), rb = split(b);
        for (size_t k = 0; k < max(ra.size(), rb.size()); k++) {
            int c = cmpRev(k < ra.size() ? ra[k] : "0", k < rb.size() ? rb[k] : "0");
            if (c != 0) return c;
        }
        return 0;
    }
};

