static int split(const char* s, const char*** starts, int** lens) {
    int n = strlen(s), parts = 1;
    for (int i = 0; i < n; i++) if (s[i] == '.') parts++;
    *starts = malloc(parts * sizeof(char*));
    *lens = malloc(parts * sizeof(int));
    int p = 0, from = 0;
    for (int i = 0; i <= n; i++)
        if (i == n || s[i] == '.') { (*starts)[p] = s + from; (*lens)[p++] = i - from; from = i + 1; }
    return parts;
}

static int cmp_rev(const char* x, int xl, const char* y, int yl) {
    while (xl > 0 && *x == '0') { x++; xl--; }
    while (yl > 0 && *y == '0') { y++; yl--; }
    if (xl != yl) return xl > yl ? 1 : -1;
    int c = strncmp(x, y, xl);
    return c > 0 ? 1 : c < 0 ? -1 : 0;
}

int compareReleases(char* a, char* b) {
    const char **sa, **sb;
    int *la, *lb;
    int na = split(a, &sa, &la), nb = split(b, &sb, &lb), answer = 0;
    for (int k = 0; k < (na > nb ? na : nb) && answer == 0; k++)
        answer = cmp_rev(k < na ? sa[k] : "0", k < na ? la[k] : 1, k < nb ? sb[k] : "0", k < nb ? lb[k] : 1);
    free(sa); free(sb); free(la); free(lb);
    return answer;
}

