class Solution:
    def compareReleases(self, a: str, b: str) -> int:
        i, j, n, m = 0, 0, len(a), len(b)
        while i < n or j < m:
            while i < n and a[i] == "0":
                i += 1
            while j < m and b[j] == "0":
                j += 1
            si, sj = i, j
            while i < n and a[i] != ".":
                i += 1
            while j < m and b[j] != ".":
                j += 1
            x, y = a[si:i], b[sj:j]
            if len(x) != len(y):
                return 1 if len(x) > len(y) else -1
            if x != y:
                return 1 if x > y else -1
            i, j = i + 1, j + 1
        return 0

