class Solution {
    public int compareReleases(String a, String b) {
        int i = 0, j = 0, n = a.length(), m = b.length();
        while (i < n || j < m) {
            while (i < n && a.charAt(i) == '0') i++;
            while (j < m && b.charAt(j) == '0') j++;
            int si = i, sj = j;
            while (i < n && a.charAt(i) != '.') i++;
            while (j < m && b.charAt(j) != '.') j++;
            if (i - si != j - sj) return i - si > j - sj ? 1 : -1;
            for (int k = 0; k < i - si; k++)
                if (a.charAt(si + k) != b.charAt(sj + k)) return a.charAt(si + k) > b.charAt(sj + k) ? 1 : -1;
            i++;
            j++;
        }
        return 0;
    }
}

